<?php
require_once __DIR__.'/config.php';
$code=trim($_GET['code']??$_POST['code']??''); $order=null; $items=[]; $paid=0;
if($code!==''){try{$s=db()->prepare("SELECT o.*,c.name customer_name FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.tracking_code=?");$s->execute([$code]);$order=$s->fetch();if($order){$s=db()->prepare("SELECT * FROM order_items WHERE order_id=?");$s->execute([$order['id']]);$items=$s->fetchAll();$s=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE order_id=?");$s->execute([$order['id']]);$paid=(float)$s->fetchColumn();}}catch(Throwable $e){}}
$steps=['Received','Washing','Drying','Ready for Pickup','Completed'];$idx=$order?array_search($order['status'],$steps):false;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track your laundry · Laundry Shop</title><link rel="stylesheet" href="assets/style.css"></head><body class="public-page"><nav class="public-nav"><a class="brand" href="index.php"><span class="brand-mark">✦</span><span>Laundry Shop<small>CARE IN EVERY CYCLE</small></span></a><a href="index.php" class="nav-link">← Home</a></nav><main class="track-wrap"><?php if(!$order): ?><div class="track-card"><span class="eyebrow">YOUR LAUNDRY, IN THE LOOP</span><h1>Track your laundry.</h1><p class="muted">Enter the unique tracking code from your receipt to see the latest progress.</p><?php if($code!==''): ?><div class="alert error">We couldn't find that tracking code. Please check it and try again.</div><?php endif; ?><form method="get" class="track-form"><input name="code" required placeholder="e.g. LD-AB12-CD34" value="<?=e($code)?>"><button class="btn primary">Track laundry →</button></form><p class="micro">Your tracking code is printed on your laundry receipt.</p></div><?php else: ?><div class="track-card"><p class="muted">Tracking code <strong><?=e($order['tracking_code'])?></strong></p><h1><?=e($order['status'])?></h1><div class="progress"><?php foreach($steps as $i=>$step): ?><div class="progress-step <?=($i<=$idx?'done':'')?> <?=($i===$idx?'current':'')?>"><span class="dot"></span><small><?=e($step)?></small></div><?php endforeach; ?></div><div class="details"><?php $rows=['Customer'=>$order['customer_name'],'Services'=>implode(', ',array_unique(array_column($items,'service_name'))),'Received'=>date('M j, Y g:i A',strtotime($order['received_at'])),'Estimated completion'=>$order['estimated_completion']?date('M j, Y g:i A',strtotime($order['estimated_completion'])):'To be confirmed','Ready since'=>$order['ready_since']?date('M j, Y g:i A',strtotime($order['ready_since'])):'—','Total'=>money($order['total']),'Paid'=>money($paid).' ('.($paid>=$order['total']?'Paid':'Unpaid / Partial').')','Balance'=>money(max(0,$order['total']-$paid))];foreach($rows as $k=>$v):?><div class="detail-row"><span><?=e($k)?></span><strong><?=e($v)?></strong></div><?php endforeach;?></div><?php if($order['notes']):?><p class="micro"><?=e($order['notes'])?></p><?php endif;?></div><a class="btn soft track-another" href="track.php">Track another</a><?php endif; ?></main><footer class="public-footer">© <?=date('Y')?> Laundry Shop · Fresh laundry. Peace of mind.</footer></body></html>
